def hydrate_time(nanoseconds, tz=None):
    """Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    if nanoseconds >= 1e9:  # 1 second
        seconds = nanoseconds // 1e9
        nanoseconds %= 1e9
        return datetime.time(hour=seconds // 3600, minute=(seconds % 3600) // 60, second=(seconds % 3600) % 60, microsecond=int(nanoseconds * 1e6))
    else:
        if tz:
            return datetime.datetime.fromtimestamp(nanoseconds, tz=tz).time()
        else:
            return datetime.datetime.fromtimestamp(nanoseconds).time()

