def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
     """
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol version must be a tuple")
        if not issubclass(protocol_version[0], Version):
            raise TypeError("protocol version 1 must be a subclass of Version")
        if not issubclass(protocol_version[1], Version):
            raise TypeError("protocol version 2 must be a subclass of Version")
        if not protocol_version[0] <= version <= protocol_version[1]:
            # if not valid range, return None as the handler doesn't support that version
            return None
    else:
        # get all supported versions
        versions = cls.ALLOWED_PROTOCOL_VERSIONS
        if not versions:
            # no supported versions, return None as there's no handler available
            return None

    handlers = {}
    for version in versions:
        try:
            handler = version.protocol_handler()
            handlers[version] = handler
        except CannotSupportProtocolVersion:
            # if handler doesn't support the version, skip it
            pass

    return handlers

