def xargs(cmd: tuple[str, ...], varargs: Sequence[str], *,
         color: bool = False,
         target_concurrency: int = 1,
         _max_length: int = _get_platform_max_length(),
         **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess
    import os

    args = [cmd[0]] + list(cmd[1:]) + varargs

    if color:
        if os.name == 'posix':
            args = ["/bin/bash", '-c', f"echo -e '{args[1]}' | xargs -0"]
        else:
            raise ValueError("color mode is not supported for this platform")

    elapsed = 0

    with subprocess.Popen(args, stdout=subprocess.PIPE, bufsize=0, universal_newlines=True, start_new_session=True, preexec_fn=os.setsid if os.name == 'posix' else None) as process:
        for line in process.stdout:
            elapsed += len(line)
            if elapsed >= _max_length:
                break
        process.poll()

    return elapsed, process.stdout.read()

def xargs(cmd: Tuple[str, ...], varargs: Sequence[str], *, color: bool = False, target_concurrency: int = 1, _max_length: int = _get_platform_max_length(), **kwargs: Any) -> Tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    if color:
        import subprocess
        pty = subprocess.Popen(cmd[:-1], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, preexec_fn=lambda: subprocess.run(["xterm", "-e"]) if os.name != 'nt' else None)
        pty.stdin.close()
        return pty.communicate(b' '.join(varargs))[0] + b'\n', pty.wait()
    else:
        return subprocess.run(cmd + [('--']+map(str, varargs) if varargs else []), stdout=subprocess.PIPE, stderr=subprocess.PIPE).stdout + b'\n', subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE).wait()

