from collections import deque

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""

    seq = deque(seq)

    for i in range(len(seq)):
        random_index = i + random.randrange(0, len(seq) - i)
        seq[i], seq[random_index] = seq[random_index], seq[i]

    return list(seq)

