def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    normalized_cmd = []
    for command in cmd:
        if command.startswith('#!'):
            if '\\' in command:
                normalized_cmd.append(command.replace('\\', '\\\\'))
            else:
                normalized_cmd.append(command)
        else:
            normalized_cmd.append(command)
    return tuple(normalized_cmd)

def replace_fragment(element: 'Fragment', from_view: 'FragmentView', to_view: 'FragmentView'):
    """Replace the fragment `from_view` with `to_view`.

    The from-view must be a direct child of the element."""

    for child in element children:
        if child == from_view:
            element.replace(child, to_view)
            return
        replace_fragment(child, from_view, to_view)

