def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    if maxsize is None:
        maxsize = 128

    from collections import OrderedDict
    from threading import Lock

    class LruCache:

        def __init__(self, maxsize, typed=False, future=False):
            self.maxsize = maxsize
            self.typed = typed
            self.future = future
            self._cache = OrderedDict()
            self._lock = Lock()
            self._future_keys = set()

        def __call__(self, func):
            def wrapper(*args, **kwargs):
                # Handle kwargs separately to allow for different types of keys (type-based or value-based)
                if self.typed:
                    kw = {k: hash(v) if isinstance(v, (int, str, float)) else k for k, v in kwargs.items()}
                else:
                    kw = {k: v for k, v in kwargs.items()}

                key = (args, kw)
                with self._lock:
                    if key in self._cache:
                        future_key = self._future_keys.get(key, None)

                        if future_key:
                            self._future_keys.remove(future_key)
                            if future_key not in self._cache.values() and len(self._cache) > 0:
                                self.kv.remove(future_key)

                        return self._cache[key]

                    if len(self._cache) >= self.maxsize:
                        # Remove the least frequently used item
                        oldest_key = next(iter(self._cache))
                        if self.future_keys.get(oldest_key, None):
                            self._future_keys.remove(oldest_key)

                        reused_key = next(iter(self.kv))

                        for k, v in self._cache.items():
                            for parent_v in v:
                                if parent_v == oldest_key:
                                    reused_key = k
                                    break

                        self._cache.renew(reused_key)
                        self._cache[reused_key], self._cache[oldest_key] = self._cache[oldest_key], self._cache[reused_key]
                        self._cache.popleft()

                # Schedule this key for a future refresh
                scheduled_key = id(future_key)
                if future_key in self._future_keys:
                    scheduled_key = self._future_keys.remove(future_key)
                self._future_keys.add(scheduled_key)

                self._cache[key] = (value, future_key)

                return value
            wrapper.__wrapped__ = func
            wrapper.maxsize = self.maxsize
            wrapper.typed = self.typed
            wrapper.future = self.future
            return wrapper

    lru_cache.kv = LruCache()  # a private instance variable for the LRU cache
    return lru_cache

