def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']
    """
    merged = {}
    for ordering in orderings:
        for entry in ordering:
            if entry in merged:
                if isinstance(entry, list):
                    merged[entry].extend(ordering[ordering.index(entry)+1:])
                else:
                    merged[entry].append(ordering[ordering.index(entry)+1])
            else:
                merged[entry] = ordering[ordering.index(entry)+1:]
    return [value for value in merged.values() if isinstance(value, list)]

