def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    base_set = set()
    for cls in classes:
        base_set.add(cls)
        for parent in cls.__bases__:
            if parent not in base_set:
                parent.set(mutable=False)
                base_set.add(parent)

    minimal_list = []
    for cls in sorted(base_set, key=lambda x: ( len(x.__subclasses__()), x.__name__)):
        minimal_list.append(cls)

    return minimal_list

