def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    self.context = {}
    if self.interval is None:
        self.initialize_bins(self.initial_value)
        self.make_bins = self.initialize_bins
    else:
        bins = self.make_bins()
        for bin in bins:
            self.context[bin] = self.initial_value

