def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == -1:
        return {k: v for k, v in d1.items() if k not in d2}

    result = {}

    for k, v in d1.items():
        if k in d2:
            if isinstance(v, dict) and isinstance(d2[k], dict):
                sub_diff = difference(v, d2[k], level - 1)
                if sub_diff:
                    result[k] = sub_diff
            elif v != d2[k]:
                result[k] = v
        else:
            result[k] = v

    return result

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both arguments must be dictionaries")

    if level == 1:
        difference_dict = {}
        for key in d1:
            if key not in d2 or d1[key] != d2[key]:
                difference_dict[key] = d1[key]
        return difference_dict

    result = {}
    for key, value in d1.items():
        if key in d2:
            if isinstance(value, dict) and isinstance(d2[key], dict):
                recursive_result = difference(value, d2[key], level - 1)
                if recursive_result:
                    result[key] = recursive_result
            elif value != d2[key]:
                result[key] = value
        else:
            result[key] = value

    return result

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == -1 or level == 0:
        diff = {}
        for key in d1:
            if key not in d2:
                diff[key] = d1[key]
            elif level == 0 and d1[key] != d2[key]:
                diff[key] = d1[key]
        return diff
    else:
        diff = {}
        for key in d1:
            if key not in d2:
                diff[key] = d1[key]
            elif level > 0:
                diff[key] = difference(d1[key], d2[key], level - 1)
        return diff

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == -1:
        d1_temp = d1.copy()
        d2_temp = d2.copy()
        for key in d1_temp:
            if key in d2_temp and d1_temp[key] != d2_temp[key]:
                yield key, d1_temp[key], d2_temp[key]
            if isinstance(d1_temp[key], dict) and isinstance(d2_temp[key], dict):
                for item in difference(d1_temp[key], d2_temp[key], level=0):
                    yield item
    elif level > 0:
        if isinstance(d1, dict):
            for key in d1:
                if key not in d2 and isinstance(d1[key], dict) and isinstance(d2[key], dict):
                    for item in difference(d1[key], d2[key], level-1):
                        yield key, item
        elif isinstance(d1, list):
            for item in d1:
                if item not in d2:
                    yield item
        elif isinstance(d1, set):
            for item in d1:
                if item not in d2:
                    yield item

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == -1 or not isinstance(d2, dict):
        return d1.copy()

    diff = {}
    for key in d1:
        if key not in d2:
            diff[key] = d1[key]
        elif isinstance(d1[key], dict) and isinstance(d2[key], dict):
            if level == 0:
                diff[key] = d1[key].copy()
            else:
                diff[key] = difference(d1[key], d2[key], level - 1)
        elif d1[key] != d2[key]:
            diff[key] = d1[key]

    return diff

def validate_labels(self, labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    error_messages = []
    for key, value in labels.items():
        if isinstance(value, str):
            if not re.match(Regex.SANS_WS_KEY, key):
                error_messages.append({"key": key, "value": "expected string or bytes-like object"})
        elif isinstance(value, list):
            for item in value:
                if not re.match(Regex.SANS_WS_VALUE, item):
                    error_messages.append({"key": key, "value": "expected string or bytes-like object"})
        elif not isinstance(value, (str, list)):
            error_messages.append({"key": key, "value": "expected string or bytes-like object"})

    if error_messages:
        raise ValidationError(error_messages)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their respective
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    validation_errors = []
    for key, value in labels.items():
        if not isinstance(key, str) and not isinstance(key, bytes):
            validation_errors.append({"key": key, "value": f"expected string or bytes-like object"})
        else:
            label_regexes = getattr(labels[key], "__label_regexes", None)
            if label_regexes:
                for regex in label_regexes:
                    if not regex.match(value):
                        validation_errors.append({"key": key, "value": f"expected {regex.pattern} but got {value}"})
            else:
                validation_errors.append({"key": key, "value": f"label '{key}' does not have a specific regex"})
    if validation_errors:
        raise ValidationError(validation_errors)

