def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    result = {}

    # Loop through each manifest in the application
    for manifest in app.spec.manifest:
        kind = manifest.kind.lower()
        api_version = manifest.api_version
        version = manifest.version

        # Check if a custom observer schema is specified
        if manifest.spec.observer_schema:
            schema = manifest.spec.observer_schema
        else:
            # Generate a default schema based on the kind and version
            schema = {
                "title": f"Default Observer Schema for {kind} v{version}",
                "type": "object",
                "properties": {
                    "metadata": {
                        "type": "object",
                        "properties": {
                            "name": {
                                "type": "string"
                            }
                        },
                        "required": ["name"]
                    },
                    "spec": {
                        "type": "object",
                        "properties": {
                            "environment": {
                                "type": "string"
                            }
                        },
                        "required": ["environment"]
                    }
                },
                "required": ["metadata", "spec"]
            }

        result[kind] = {
            "apiVersion": api_version,
            "version": version,
            "schema": schema
        }

    return result

