def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Check if the fixity block contains files listed in the manifest
    for file in fixity.files:
        if file in manifest_files:
            if not file in manifest_files[file]:
                raise ValueError("File " + file + " not found in manifest.")
        else:
            raise ValueError("File " + file + " not listed in fixity block.")

if not fixity:
            return True

        for file, expected_checksum in fixity.items():
            file_path = os.path.join(self.inventory_dir, file)
            if not os.path.exists(file_path):
                return False

            with open(file_path, 'rb') as f:
                actual_checksum = hashlib.sha256(f.read()).hexdigest()
                if actual_checksum != expected_checksum:
                    return False

        return True

