def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = args.copy()

    for i in range(len(result)):
        for j in range(i+1, len(result)):
            if isinstance(result[i], Expression) and isinstance(result[j], Expression):
                if result[i] == result[j] or result[i] & (result[j] | result[i]) == result[i]:
                    result.remove(result[i])

                if result[j] == result[i] or result[j] & (result[i] | result[j]) == result[j]:
                    result.remove(result[j])

    return result

