import os

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    command = ['command'] + commands

    if args:
        command.extend(args)

    if cwd:
        os.chdir(cwd)

    if verbose:
        print(" ".join(command))
    else:
        # Run the command silently
        if not hide_stderr:
            subprocess.run(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
        else:
            subprocess.run(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, env=env)

