def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        # Start variable to hold the total number of objects checked
        num_objects = 0

        # Start variable to hold the number of valid objects
        good_objects = 0

        # Iterate over all children of the current object
        for child in self.children:
            num_objects += 1

            # Initialize a flag to tell if the child is valid
            child_valid = True

            # If the validate_objects argument is set to True, check the child
            if validate_objects:
                try:
                    if not child.is_valid():
                        child_valid = False
                except AttributeError:
                    if show_warnings:
                        print("Warning: child object does not have an is_valid() method.")

            # If the check_digests argument is set to True, check the child's digest
            if check_digests:
                try:
                    if child.digest != child.calculate_digest():
                        child_valid = False
                except AttributeError:
                    if show_warnings:
                        print("Warning: child object does not have a digest and calculate_digest() method.")

            # If the child is still valid, increment the number of valid objects
            if child_valid:
                good_objects += 1

        # Return the total number of objects checked and the number of valid objects
        return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Walk through the storage root hierarchy
    for element in self:
        num_objects += 1
        if validate_objects:
            if not self.validate_element(element):
                show_warnings = False  # Don't show warnings for invalid objects based on the returned status
        else:
            good_objects += 1 if self.validate_element(element) else 0

        # Check digests if required
        if check_digests:
            self.check_digests(element, show_warnings)

        # Recursively validate sub-elements
        if element.__class__.is_descendant:
            good_objects += self.validate_hierarchy(validate_objects, check_digests, show_warnings)

    return num_objects, good_objects

