    """Amend the Bugzilla params"""

    for bug_id in bug_ids:
        bug = params.bugs.get(bug_id)
        if bug:
            bug['fix'] = self.fix
            bug['priority'] = self.priority
            bug['description'] = self.description
            bug['long_desc'] = self.long_desc
            bug['component'] = self.component
            bug['product'] = self.product
        else:
            params.bugs[bug_id] = {'fix': self.fix, 'priority': self.priority, 'description': self.description, 'long_desc': self.long_desc, 'component': self.component, 'product': self.product}

