        split = arg.split("=", 1)
        if len(split) == 1:
            remaining_args.append(arg)
        else:
            name, value = split
            if name in parsed_args:
                if parsed_args[name] is not None:
                    if isinstance(parsed_args[name], tuple) or isinstance(parsed_args[name], list):
                       parsed_args[name].append(value)
