        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]
    """


    def merge(key, value, merged):
        if value is None:
            return

        if isinstance(value, dict):
            # if the key already exists in the combined dictionary, merge the values recursively
            if key in merged:
                merged[key].update(value)
            else:
                merged[key] = value
        else:
            # Otherwise, update the existing value if it exists, or add it if it doesn't
            if key in merged:
                merged[key] = value
            else:
                merged[key] = [value]

    merged = {}
    for key_node, value_node in nodes:
        merge(key_node.value, value_node.value, merged)
    return list(merged.items())

