def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::
            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if size.endswith("B"):
        return int(size[:-1])
    elif size.endswith("K"):
        return int(size[:-1]) * 1024
    elif size.endswith("M"):
        return int(size[:-1]) * 1048576
    elif size.endswith("G"):
        return int(size[:-1]) * 1073741824
    else:
        raise ValueError(f"Unsupported file size unit: {size}")

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.lower()

    if size.endswith('gb'):
        return int(size.rstrip('gb')) * 1024 * 1024 * 1024
    elif size.endswith('mb'):
        return int(size.rstrip('mb')) * 1024 * 1024
    elif size.endswith('k'):
        return int(size.rstrip('k'))
    elif size.endswith('m'):
        return int(size.rstrip('m'))

    raise ValueError("Invalid file size format")

