def vertex3tuple(vertices):
    if not isinstance(vertices, (list, tuple)):
        raise ValueError("Input must be a list or tuple of vertices")
    if len(vertices) < 3:
        raise ValueError("Input list must contain at least 3 vertices")
    vertices = list(vertices)
    while len(vertices) > 3:
        vertices.pop(0)  # remove the first vertex
    while len(vertices) > 2:
        vertices.append(vertices[0])  # duplicate the last two vertices
    return tuple((vertices[i], vertices[(i+1) % 3], vertices[(i+2) % 3]) for i in range(len(vertices)))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is None:
        padding = 0

    digits = []
    while number > 0:
        digits.insert(0, alphabet[number % len(alphabet)])
        number //= len(alphabet)

    return ''.join(digits) + '0' * max(0, padding - len(digits))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number == 0:
        return alphabet[0]
    digits = []
    while number > 0:
        digits.append(alphabet[number % len(alphabet)])
        number = number // len(alphabet)
    return ''.join(reversed(digits))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is not None and padding < 0:
        raise ValueError("Padding cannot be negative")

    digits = []
    while number > 0:
        digits.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    if padding is not None:
        digits = digits.zfill(padding)

    return ''.join(digits[::-1])

