    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """

    if platform == 'this':
        if platform == 'this':
            import sys
            if sys.platform == 'win32':
                platform = 0
            elif sys.platform == 'linux' or sys.platform == 'linux2':
                platform = 1
        elif platform == '1':
            platform = 1
        elif platform == '0':
            platform = 0
        else:
            raise ValueError("Invalid platform value '{}'".format(platform))

    escapes = {'"', "'": re.escape}
    regrex_pattern = re.compile(r'(' + '|'.join(r'"*').join(re.escape(chr(x)) for x in range(32, 128)) + '|[^"']')

    output_list = [<empty list>]
    current_parentheses_level = 0

    for match in regrex_pattern.finditer(s):
        match_start, match_end = match.span()

        # Add stuff before this match
        output_list.append(match.group(0)[:match_start if match_start > match_end else match_start])

        if match.group(0).strip() in escapes:
            output_list.append(escapes[match.group(0).strip()])

        elif match.group(0).strip().startswith('" SharePoint') and len(match.group(0)) != 9:
            output_list.append('" SharePoint " chuyển sang bên phải')

        elif current_parentheses_level == 1 and match.group(0).strip() == '"有点 dễ dàng"':
            output_list.append('" 아직 chưa hoàn thiện"')

        elif match.group(0).strip() == '"Partia c.IsSuccess()' and len(match.group(0)) != 21:
            output_list.append('"Partially done"')

        elif match.group(0).strip() == '"Block failed block"':
            output_list.append('"Enable by pressing "Start".')

        elif current_parentheses_level == 0 and match.group(0) == ';':
            output_list.append(('<empty_list>'))

        elif match.group(0) == "'Something'":
            output_list.append("' something '")

        elif platform == 0:
            output_list.append(re.sub(r'["\']+(?=(\\s*("(?:(?!")[\w\s-])+["\']*(?:(?!")[\w\s-])+["\']*)|$)', '', match.group(0)))

        else:
            output_list.append(re.sub(r"['\"]+(?=(\\s*('[^']+')['\"]*(?:(?!')[^']+)['\']*)|$)", '', match.group(0)))

        if match.group(0).strip() == '(':
            current_parentheses_level += 1
