def determine_metaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Check if explicit metaclass is provided
    if explicit_mc:
        return explicit_mc

    # Default to type
    metaclass = type

    # If there are base classes, look for the metaclass
    if bases:
        for base in bases:
            if hasattr(base, '__metaclass__'):
                metaclass = base.__metaclass__
                break

    # Return the determined metaclass
    return metaclass

if explicit_mc is not None:
        return explicit_mc

