    # Try the bases first
    candidates = [c for c in bases if getattr(c, '__metaclass__', None) == cfg]

    if cfgoppel:
        if not candidates:
            candidates = [c for c in bases if getattr(c, '__mro__', None) and len(c.__mro__) > 1]
    else:
        if not candidates:
            candidates = [c for c in bases if getattr(c, '__mro__', None)]

    if candidates:
        meta = candidates[0]
    else:
        meta = cfg

    return meta

