def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    in_code_block = False

    for char in text:
        if char == '`':
            in_code_block = not in_code_block
        elif not in_code_block:
            if char == '<':
                tag_start = text.index('<', text.index('<') + 1)
                tag_end = text.index('>', tag_start)
                tag = text[tag_start:tag_end + 1]
                if tag not in tags:
                    tags.add(tag)
        elif replacer is not None:
            text = text.replace(tag, replacer(tag))

    return tags, text

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    # Split text into words
    words = text.split()

    processed_words = []
    seen_links = set()  # To detect cycles in link chains

    for word in words:
        # Check for a link
        if word.lower().startswith('http://') or word.lower().startswith('https://'):
            link = word
            if link in seen_links:
                # Cycle detected, raise error
                raise ValueError("Cycle detected in link chain")

            seen_links.add(link)
            processed_words.append(f"<!-- Link: {link} -->")

            # Linkify the link
            processed_words.append(f'<a href="{link}">{word}</a>')

        else:
            processed_words.append(word)

    return ''.join(processed_words)

